-- The official banks' source, one row per list element, loaded by each official_bank_* migration that follows.
-- Only migrations read it: no student, visitor or service key can.
create table private.official_bank_rows (
  bank text not null,
  part text not null check (part in ('bank', 'audited', 'keep', 'retire', 'add')),
  ordinal integer not null check (ordinal >= 0),
  value jsonb not null,
  primary key (bank, part, ordinal)
