revoke all on table private.official_bank_rows from public, anon, authenticated, service_role;

-- One bank as a single document: its summary row's scalars, then each list in ordinal order. Refused when the summary
-- row is missing, is another course's, or any list has a different number of rows than the summary records.
create function private.official_bank_source(p_bank text, p_code text)
returns jsonb language plpgsql stable security invoker set search_path = '' as $official_bank_source$
declare
  v_summary jsonb := (select r.value from private.official_bank_rows r
    where r.bank = p_bank and r.part = 'bank' and r.ordinal = 0);
  v_bank jsonb := (v_summary - 'rows') || jsonb_build_object(
    'audited', coalesce((select jsonb_agg(r.value order by r.ordinal)
      from private.official_bank_rows r where r.bank = p_bank and r.part = 'audited'), '[]'),
    'keep', coalesce((select jsonb_agg(r.value order by r.ordinal)
      from private.official_bank_rows r where r.bank = p_bank and r.part = 'keep'), '[]'),
    'retire', coalesce((select jsonb_agg(r.value order by r.ordinal)
      from private.official_bank_rows r where r.bank = p_bank and r.part = 'retire'), '[]'),
    'add', coalesce((select jsonb_agg(r.value order by r.ordinal)
      from private.official_bank_rows r where r.bank = p_bank and r.part = 'add'), '[]'));
begin
  if v_summary is null or v_summary->>'code' is distinct from p_code or exists (
      select 1 from unnest(array['audited', 'keep', 'retire', 'add']) p(part)
      where (v_summary->'rows'->>p.part)::integer is distinct from jsonb_array_length(v_bank->p.part)) then
    raise exception 'Official bank %: its source rows are missing', p_code;
  end if;
  return v_bank;
end;
